import React, { useState, useRef } from 'react';
import axios from 'axios';

// A simple icon component for better UI
const UploadIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
      <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
    </svg>
);

function FileUpload() {
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [parentFolderId, setParentFolderId] = useState('');

  const fileInputRef = useRef(null);

  // --- Step 1: Check if the environment variable is loaded ---
  // If VITE_API_URL is not set, the app can't work.
  // This provides a clearer error message during development.
  if (!import.meta.env.VITE_API_URL) {
    return (
        <div className="card p-6 shadow-lg rounded-xl bg-red-50 border-red-500 text-red-800 max-w-xl mx-auto mt-8">
          <h2 className="text-2xl font-bold mb-4">Configuration Error</h2>
          <p className="font-semibold">The API URL is not configured.</p>
          <p className="mt-2">Please ensure you have a <code className="bg-red-200 p-1 rounded">.env</code> file in your project's root directory with the following content:</p>
          <pre className="bg-red-200 p-2 rounded mt-2 text-sm">
                VITE_API_URL=http://localhost:8080
            </pre>
          <p className="mt-4 font-bold">After creating or editing the <code className="bg-red-200 p-1 rounded">.env</code> file, you MUST restart your development server.</p>
        </div>
    );
  }

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      setFile(selectedFile);
      setMessage('');
      setError('');
    }
  };

  const handleParentFolderChange = (e) => {
    setParentFolderId(e.target.value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!file) {
      setError('Please select a file to upload.');
      return;
    }

    const MAX_SIZE_MB = 20;
    if (file.size > MAX_SIZE_MB * 1024 * 1024) {
      setError(`File size should not exceed ${MAX_SIZE_MB} MB. Your file is ${(file.size / 1024 / 1024).toFixed(2)} MB.`);
      return;
    }

    setLoading(true);
    setMessage('');
    setError('');

    const formData = new FormData();
    formData.append('file', file);

    if (parentFolderId) {
      formData.append('parentFolderId', parentFolderId);
    }

    try {
      // Use the environment variable to build the full API endpoint
      const apiUrl = `${import.meta.env.VITE_API_URL}/api/files/upload`;

      const response = await axios.post(apiUrl, formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      setMessage('File uploaded successfully!');
      setFile(null);
      setParentFolderId(''); // Optionally clear the folder ID as well

      // Reset the file input
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }

      // Trigger global custom event to refresh file list in other components
      window.dispatchEvent(new CustomEvent('fileUploaded'));

    } catch (err) {
      if (err.response) {
        // Server responded with an error (e.g., 400, 404, 500)
        setError(err.response.data.message || err.response.data || 'Failed to upload file. The server returned an error.');
      } else if (err.request) {
        // Request was made but no response was received
        setError('No response from server. Please check your network connection and ensure the API server is running.');
      } else {
        // Something else happened in setting up the request
        setError('An unexpected error occurred. Please check the console for details.');
      }
      console.error('Error uploading file:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
      <div className="font-sans bg-gray-50 flex items-center justify-center p-4">
        <div className="card p-6 shadow-lg rounded-xl bg-white max-w-xl w-full mx-auto">
          <h2 className="text-2xl font-bold mb-5 text-gray-800 border-b pb-3">Upload New File</h2>

          {message && <div className="p-3 mb-4 rounded-lg bg-green-100 text-green-800 border border-green-200">{message}</div>}
          {error && <div className="p-3 mb-4 rounded-lg bg-red-100 text-red-800 border border-red-200">{error}</div>}

          <form onSubmit={handleSubmit} noValidate>
            <div className="mb-4">
              <label htmlFor="fileInput" className="block font-medium text-gray-700 mb-1">
                Select File
              </label>
              <input
                  type="file"
                  id="fileInput"
                  ref={fileInputRef}
                  className="form-control file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-violet-50 file:text-violet-700 hover:file:bg-violet-100 block w-full text-sm text-gray-500 border rounded-lg cursor-pointer focus:outline-none"
                  onChange={handleFileChange}
              />
            </div>

            <div className="mb-6">
              <label htmlFor="parentFolderId" className="block font-medium text-gray-700 mb-1">
                Parent Folder ID (Optional)
              </label>
              <input
                  type="text"
                  id="parentFolderId"
                  value={parentFolderId}
                  onChange={handleParentFolderChange}
                  className="form-control border rounded-lg p-2 w-full focus:ring-2 focus:ring-violet-500 focus:border-violet-500 outline-none"
                  placeholder="Leave empty to upload to root"
              />
            </div>

            <button
                type="submit"
                className={`w-full flex items-center justify-center btn bg-violet-600 text-white px-4 py-2.5 rounded-lg hover:bg-violet-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-violet-500 disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors duration-300`}
                disabled={loading || !file}
            >
              <UploadIcon />
              {loading ? 'Uploading...' : 'Upload File'}
            </button>
          </form>
        </div>
      </div>
  );
}

export default FileUpload;
